class Solution { public int minimizeConcatenatedLength(String[] words){int inf=1000000000;int[][] dp=new int[26][26];for(int[] row:dp)Arrays.fill(row,inf);String firstWord=words[0];dp[firstWord.charAt(0)-'a'][firstWord.charAt(firstWord.length()-1)-'a']=firstWord.length();for(int index=1;index<words.length;index++){String word=words[index];int a=word.charAt(0)-'a',b=word.charAt(word.length()-1)-'a',length=word.length();int[][] next=new int[26][26];for(int[] row:next)Arrays.fill(row,inf);for(int first=0;first<26;first++)for(int last=0;last<26;last++)if(dp[first][last]<inf){next[first][b]=Math.min(next[first][b],dp[first][last]+length-(last==a?1:0));next[a][last]=Math.min(next[a][last],dp[first][last]+length-(b==first?1:0));}dp=next;}int answer=inf;for(int[] row:dp)for(int value:row)answer=Math.min(answer,value);return answer;} }
